#ifdef NS_OPCODE_STATS
uint32_t ns_opcodeStats[256]; /* how often each opcode runs: decides the ranks (tools/import_cpu.py) */
#endif

__attribute__((noinline)) void cpu_run(Snes* s) {
  Cpu* cpu = &s->cpu;
  if(cpu->resetWanted) cpu_doReset(cpu);
  for(;;) {
    if(NS_UNLIKELY(cpu->special)) {
      if(!cpu_special(cpu)) return;
      continue;
    }
    const uint32_t opcode = cpu_readOpcode(cpu);
#ifdef NS_OPCODE_STATS
    ns_opcodeStats[opcode]++;
#endif
    uint32_t low = 0;
    uint32_t high = 0;
    switch(kMode[opcode]) {
      case M_Dp: high = cpu_adrDp(cpu, &low); break;
      case M_Abs: high = cpu_adrAbs(cpu, &low); break;
      case M_ImmM: high = cpu_adrImm(cpu, &low, false); break;
      case M_AbxR: high = cpu_adrAbx(cpu, &low, false); break;
      case M_Ily: high = cpu_adrIly(cpu, &low); break;
      case M_Idl: high = cpu_adrIdl(cpu, &low); break;
      case M_AbxW: high = cpu_adrAbx(cpu, &low, true); break;
      case M_ImmX: high = cpu_adrImm(cpu, &low, true); break;
      case M_Alx: high = cpu_adrAlx(cpu, &low); break;
      case M_AbyR: high = cpu_adrAby(cpu, &low, false); break;
      case M_AbyW: high = cpu_adrAby(cpu, &low, true); break;
      case M_Dpx: high = cpu_adrDpx(cpu, &low); break;
      case M_Abl: high = cpu_adrAbl(cpu, &low); break;
      case M_IdyR: high = cpu_adrIdy(cpu, &low, false); break;
      case M_Idp: high = cpu_adrIdp(cpu, &low); break;
      case M_Idx: high = cpu_adrIdx(cpu, &low); break;
      case M_Sr: high = cpu_adrSr(cpu, &low); break;
      case M_Isy: high = cpu_adrIsy(cpu, &low); break;
      case M_IdyW: high = cpu_adrIdy(cpu, &low, true); break;
      case M_Dpy: high = cpu_adrDpy(cpu, &low); break;
      default: break;
    }
    kOp[opcode](cpu, low, high);
  }
}
